CREATE TABLE market_price_revisions(event_id UUID PRIMARY KEY,provider VARCHAR(80) NOT NULL,delivery_start TIMESTAMPTZ NOT NULL,delivery_end TIMESTAMPTZ NOT NULL CHECK(delivery_end>delivery_start),price_gbp_mwh NUMERIC(19,6) NOT NULL,source_revision VARCHAR(100) NOT NULL,source_timestamp TIMESTAMPTZ NOT NULL,retrieved_at TIMESTAMPTZ NOT NULL,correlation_id UUID NOT NULL);
CREATE INDEX market_price_history_idx ON market_price_revisions(provider,delivery_start,source_timestamp,retrieved_at,event_id);
CREATE TABLE current_market_prices(provider VARCHAR(80) NOT NULL,delivery_start TIMESTAMPTZ NOT NULL,event_id UUID NOT NULL REFERENCES market_price_revisions(event_id),delivery_end TIMESTAMPTZ NOT NULL,price_gbp_mwh NUMERIC(19,6) NOT NULL,source_revision VARCHAR(100) NOT NULL,source_timestamp TIMESTAMPTZ NOT NULL,retrieved_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(provider,delivery_start));
